const std = @import("std");

const Point = struct {
    x: i32,
    y: i32,
};

fn makePoint(allocator: std.mem.Allocator, x: i32, y: i32) !*Point {
    const point = try allocator.create(Point);
    point.* = .{ .x = x, .y = y };
    return point;
}

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const point = try makePoint(allocator, 3, 4);
    defer allocator.destroy(point);
    std.debug.print("{d},{d}\n", .{ point.x, point.y });
}
